public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    int maxLength = 0;

    // Try all possible substrings of the first string
    String firstString = strings.get(0);
    int n = firstString.length();

    for (int start = 0; start < n; start++) {
        for (int end = start + 1; end <= n; end++) {
            String substring = firstString.substring(start, end);
            String inverseSubstring = new StringBuilder(substring).reverse().toString();

            boolean allContain = true;
            for (String s : strings) {
                if (!s.contains(substring) && !s.contains(inverseSubstring)) {
                    allContain = false;
                    break;
                }
            }

            if (allContain) {
                maxLength = Math.max(maxLength, substring.length());
            }
        }
    }

    return maxLength;
}

