public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0) {
        return 0;
    }

    int numRows = grid.length;
    int numCols = grid[0].length;
    boolean[][] visited = new boolean[numRows][numCols];
    int depositCount = 0;

    for (int i = 0; i < numRows; i++) {
        for (int j = 0; j < numCols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                depositCount++;
                markDeposit(grid, visited, i, j);
            }
        }
    }

    return depositCount;
}

private static void markDeposit(char[][] grid, boolean[][] visited, int row, int col) {
    if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] == '*' || visited[row][col]) {
        return;
    }

    visited[row][col] = true;

    // Explore all 8 possible directions
    markDeposit(grid, visited, row - 1, col); // North
    markDeposit(grid, visited, row + 1, col); // South
    markDeposit(grid, visited, row, col - 1); // West
    markDeposit(grid, visited, row, col + 1); // East
    markDeposit(grid, visited, row - 1, col - 1); // Northwest
    markDeposit(grid, visited, row - 1, col + 1); // Northeast
    markDeposit(grid, visited, row + 1, col - 1); // Southwest
    markDeposit(grid, visited, row + 1, col + 1); // Southeast
}

