    int depositCount = 0;

    boolean[][] visited = new boolean[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                dfs(grid, visited, i, j, rows, cols);
                depositCount++;
            }
        }
    }

    return depositCount;
}

private static void dfs(char[][] grid, boolean[][] visited, int row, int col, int rows, int cols) {
    if (row < 0 || row >= rows || col < 0 || col >= cols || grid[row][col] != '@' || visited[row][col]) {
        return;
    }

    visited[row][col] = true;

    // Visit all 8 adjacent cells
    for (int i = -1; i <= 1; i++) {
        for (int j = -1; j <= 1; j++) {
            dfs(grid, visited, row + i, col + j, rows, cols);
        }
    }
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    if (N == 0) {
        return 1;
    }
    if (N == 1) {
        return 2;
    }
    // The formula for the maximum number of regions created by N triangles in a plane
    // is given by R(N) = 2 + 7N - 3N*(N-1)/2
    // This formula comes from the fact that each new triangle can intersect with all previous triangles
    // in 6 new intersection points, creating additional regions.
    return 2 + 7 * N - (3 * N * (N - 1)) / 2;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles must be non-negative");
    }
    return (int) Math.pow(2, N + 1);
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles must be non-negative");
    }
    // The formula to calculate the maximum number of regions is 2 * (2^N)
    return 2 * (1 << N);
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles must be non-negative");
    }
    return (N * (N + 1) * (N + 2) / 6) + 2;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles cannot be negative");
    }
    // The formula to calculate the maximum number of regions is derived from the pattern:
    // 1 triangle divides the plane into 2 regions,
    // 2 triangles can divide the plane into 8 regions, and so on.
    // The general formula is: R(N) = 2 * (N^2) + 2
    return 2 * (N * N) + 2;
}

