public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (paths == null || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }

    // Create an adjacency list to represent the graph
    Map<String, List<String>> graph = new HashMap<>();
    for (int[] path : paths) {
        if (path.length != 4) continue; // Each path must have exactly 4 coordinates
        String node1 = path[0] + "," + path[1];
        String node2 = path[2] + "," + path[3];
        graph.computeIfAbsent(node1, k -> new ArrayList<>()).add(node2);
        graph.computeIfAbsent(node2, k -> new ArrayList<>()).add(node1);
    }

    // Use BFS to check if there is a path from start to end
    String startNode = start[0] + "," + start[1];
    String endNode = end[0] + "," + end[1];
    Queue<String> queue = new LinkedList<>();
    Set<String> visited = new HashSet<>();
    queue.add(startNode);
    visited.add(startNode);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endNode)) {
            return "can be travelled";
        }
        for (String neighbor : graph.getOrDefault(current, new ArrayList<>())) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

