    if (start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    if (start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    if (n <= 0) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    boolean canTravel = dfs(start[0], start[1], end[0], end[1], paths, visited, n);
    return canTravel ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int endX, int endY, int[][] paths, boolean[][] visited, int n) {
    if (x < 0 || x >= n || y < 0 || y >= n || visited[x][y]) {
        return false;
    }
    if (x == endX && y == endY) {
        return true;
    }

    visited[x][y] = true;

    for (int[] path : paths) {
        int nextX = path[0];
        int nextY = path[1];

        if (dfs(nextX, nextY, endX, endY, paths, visited, n)) {
            return true;
        }
    }

    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }

    boolean[][] visited = new boolean[n][n];
    boolean canTravel = dfs(start[0], start[1], end[0], end[1], paths, visited);

    return canTravel ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int ex, int ey, int[][] paths, boolean[][] visited) {
    if (x == ex && y == ey) {
        return true;
    }

    visited[x][y] = true;

    for (int[] path : paths) {
        if (path[0] == x && path[1] == y && !visited[path[2]][path[3]]) {
            if (dfs(path[2], path[3], ex, ey, paths, visited)) {
                return true;
            }
        } else if (path[2] == x && path[3] == y && !visited[path[0]][path[1]]) {
            if (dfs(path[0], path[1], ex, ey, paths, visited)) {
                return true;
            }
        }
    }

    return false;
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Words cannot be null");
    }

    word1 = word1.toUpperCase();
    word2 = word2.toUpperCase();

    int[] count1 = new int[26];
    int[] count2 = new int[26];

    for (char c : word1.toCharArray()) {
        count1[c - 'A']++;
    }
    for (char c : word2.toCharArray()) {
        count2[c - 'A']++;
    }

    int common = 0;
    for (int i = 0; i < 26; i++) {
        common += Math.min(count1[i], count2[i]);
    }

    int sumLengths = word1.length() + word2.length();
    int gcd = gcd(common, sumLengths);

    String result = "appx(" + word1 + ", " + word2 + ") = " + (common / gcd) + "/" + (sumLengths / gcd);
    if (common == 0) {
        result = "appx(" + word1 + ", " + word2 + ") = 0";
    } else if (sumLengths == common) {
        result = "appx(" + word1 + ", " + word2 + ") = 1";
    }
    return result;
}

