public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        throw new IllegalArgumentException("Array must not be null or empty");
    }

    int n = arr.length;
    int removeCount = n / 20; // 5% of the elements

    // Sort the array to remove the smallest and largest 5%
    java.util.Arrays.sort(arr);

    // Calculate the sum of the remaining elements
    double sum = 0;
    for (int i = removeCount; i < n - removeCount; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the remaining elements
    int remainingCount = n - 2 * removeCount;
    return sum / remainingCount;
}

