public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int k = 0; k <= sum; k++) {
                dp[i][j][k] = dp[i - 1][j][k];
                int current = nums[i - 1];
                if (k >= current) {
                    dp[i][j][k] |= dp[i - 1][j - 1][k - current];
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[n][i][sum * i / n]) {
            return true;
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
