    boolean[][] dp = new boolean[n / 2 + 1][sum + 1];
    dp[0][0] = true;

    for (int num : nums) {
        for (int i = Math.min(n / 2, num); i >= 1; i--) {
            for (int j = sum - num; j >= 0; j--) {
                if (dp[i - 1][j]) {
                    dp[i][j + num] = true;
                }
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && dp[i][sum * i / n]) {
            return true;
        }
    }

    return false;
}

