    return dfs(nums, 0, 0, 0, 0, sum, visited);
}

private boolean dfs(int[] nums, int index, int count, int sum, int total, int totalSum, boolean[][] visited) {
    if (index == nums.length) {
        return count != 0 && count != nums.length && (sum * nums.length == total * totalSum);
    }

    if (visited[count][sum]) {
        return false;
    }

    // Include the current element in the first group
    if (dfs(nums, index + 1, count + 1, sum + nums[index], total + 1, totalSum, visited)) {
        return true;
    }

    // Exclude the current element from the first group
    if (dfs(nums, index + 1, count, sum, total, totalSum, visited)) {
        return true;
    }

    visited[count][sum] = true;
    return false;
}

