    boolean[][][] dp = new boolean[n + 1][n / 2 + 1][sum + 1];
    dp[0][0][0] = true;

    for (int i = 1; i <= n; i++) {
        int num = nums[i - 1];
        for (int j = Math.min(i, n / 2); j >= 1; j--) {
            for (int k = 0; k <= sum; k++) {
                if (dp[i - 1][j][k]) {
                    dp[i][j][k] = true;
                    if (k + num <= sum) {
                        dp[i][j + 1][k + num] = true;
                    }
                }
            }
        }
    }

    for (int j = 1; j <= n / 2; j++) {
        for (int k = 0; k <= sum; k++) {
            if (dp[n][j][k] && (Math.multiplyExact(k, n) == Math.multiplyExact(sum, j))) {
                return true;
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length < 2) {
        throw new IllegalArgumentException("Cost array must contain at least two elements.");
    }

    int[] dp = new int[cost.length + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= cost.length; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[cost.length];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int[] dp = new int[cost.length];
    dp[0] = cost[0];
    dp[1] = cost[1];

    for (int i = 2; i < cost.length; i++) {
        dp[i] = cost[i] + Math.min(dp[i - 1], dp[i - 2]);
    }

    return Math.min(dp[cost.length - 1], dp[cost.length - 2]);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int first = cost[0];
    int second = cost[1];

    for (int i = 2; i < cost.length; i++) {
        int current = cost[i] + Math.min(first, second);
        first = second;
        second = current;
    }

    return Math.min(first, second);
}

