    }

    int n = cost.length;
    if (n == 1) {
        return cost[0];
    }
    if (n == 2) {
        return Math.min(cost[0], cost[1]);
    }

    int first = cost[0];
    int second = cost[1];

    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(first, second);
        first = second;
