    Set<String> found = new HashSet<>();
    int totalPossible = 1 << k; // 2^k
    for (int i = 0; i <= s.length() - k; i++) {
        found.add(s.substring(i, i + k));
        if (found.size() == totalPossible) {
            return true;
        }
    }
    return found.size() == totalPossible;
}

