public boolean hasAllCodes(String s, int k) {
    if (s == null || s.length() == 0 || k <= 0) {
        return false;
    }

    int totalPossibleSubstrings = 1 << k; // 2^k
    boolean[] seen = new boolean[totalPossibleSubstrings];

    int val = 0;
    int mask = totalPossibleSubstrings - 1; // To keep only last k bits

    for (int i = 0; i < s.length(); i++) {
        val = (val << 1) & mask | (s.charAt(i) - '0');
        if (i >= k - 1 && !seen[val]) {
            seen[val] = true;
            totalPossibleSubstrings--;
            if (totalPossibleSubstrings == 0) {
                return true;
            }
        }
    }

    return false;
}

