public int minInsertions(String s) {
    int open = 0; // To track unmatched '('
    int insertions = 0; // To track the number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            open++; // Increment open for '('
        } else {
            // For ')'
            if (open == 0) {
                // No matching '(', need to insert one '('
                insertions++;
            } else {
                // Matching '(', decrement open
                open--;
            }
            // Check for consecutive '))'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')'
            } else {
                // Need one more ')' to make it a pair
                insertions++;
            }
        }
    }

    // Add insertions for any unmatched '('
    insertions += open * 2;

    return insertions;
}

public int minInsertions(String s) {
    int openNeeds = 0; // Number of '(' needed to balance ')'
    int insertions = 0; // Total number of insertions made

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            openNeeds += 2; // Each '(' needs two ')' to balance if followed by ')'
            if (openNeeds % 2 == 1) {
                // If we have an odd number, we need to insert a ')' to make it even
                insertions++;
                openNeeds--;
            }
        } else {
            openNeeds--; // Encountered a ')', so decrement openNeeds
            if (openNeeds == -1) {
                // More ')' than '(' encountered, insert a '(' to balance
                insertions++;
                openNeeds = 1; // Reset openNeeds to 1 as we inserted '('
            }
        }
    }

    return insertions + openNeeds; // Add remaining openNeeds to insertions
}

