        if (c == '(') {
            open++;
        } else { // c == ')'
            if (open > 0) {
                open--;
            } else {
                // Need to insert a '(' to match this ')'
                insertions++;
            }
            // Check for consecutive ')'
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++; // Skip the next ')'
            } else {
                // Need to insert a ')' to make it a pair
                insertions++;
            }
        }
    }
    // Each remaining '(' needs a ')'
    insertions += open * 2;
    return insertions;
}

