public int minInsertions(String s) {
    int left = 0, right = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (right % 2 == 1) {
                left++;
                right--;
            }
            right += 2;
        } else {
            right--;
            if (right == -1) {
                left++;
                right = 1;
            }
        }
    }
    return left + right;
}

