public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (high < low) return result;

    for (int i = 0; i <= 9; i++) {
        if (i >= low && i <= high) {
            result.add(i);
        }
        dfs(i, low, high, result);
    }

    Collections.sort(result);
    return result;
}

private static void dfs(int num, int low, int high, List<Integer> result) {
    if (num > high) return;

    int lastDigit = num % 10;
    int nextNumUp = num * 10 + (lastDigit + 1);
    int nextNumDown = num * 10 + (lastDigit - 1);

    if (nextNumUp <= high && lastDigit != 9) {
        if (nextNumUp >= low) {
            result.add(nextNumUp);
        }
        dfs(nextNumUp, low, high, result);
    }

    if (nextNumDown >= low && lastDigit != 0) {
        if (nextNumDown <= high) {
            result.add(nextNumDown);
        }
        dfs(nextNumDown, low, high, result);
    }
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    // Add all single-digit numbers that are within the range
    for (int i = low; i <= Math.min(high, 9); i++) {
        result.add(i);
    }

    // BFS to find all stepping numbers
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        if (i >= low) {
            queue.offer(i);
        }
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();

        if (num > high) {
            continue;
        }

        int lastDigit = num % 10;
        int nextNum1 = num * 10 + (lastDigit + 1);
        int nextNum2 = num * 10 + (lastDigit - 1);

        if (lastDigit == 0) {
            if (nextNum1 <= high) {
                queue.offer(nextNum1);
                if (nextNum1 >= low) {
                    result.add(nextNum1);
                }
            }
        } else if (lastDigit == 9) {
            if (nextNum2 <= high) {
                queue.offer(nextNum2);
                if (nextNum2 >= low) {
                    result.add(nextNum2);
                }
            }
        } else {
            if (nextNum1 <= high) {
                queue.offer(nextNum1);
                if (nextNum1 >= low) {
                    result.add(nextNum1);
                }
            }
            if (nextNum2 <= high) {
                queue.offer(nextNum2);
                if (nextNum2 >= low) {
                    result.add(nextNum2);
                }
            }
        }
    }

    // Sort the result list
    Collections.sort(result);
    return result;
}

