private static void bfs(int num, int low, int high, List<Integer> result) {
    Queue<Integer> queue = new LinkedList<>();
    queue.add(num);

    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current > high) continue;
        if (current >= low) {
            result.add(current);
        }

        int lastDigit = current % 10;
        if (lastDigit > 0) {
            int next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.add(next);
            }
        }
        if (lastDigit < 9) {
            int next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.add(next);
            }
        }
    }
}

