public static List<String> centerSymmetricNumbers(int n) {
    if (n < 1) {
        return Collections.emptyList();
    }
    return helper(n, n);
}

private static List<String> helper(int n, int finalLength) {
    if (n == 0) {
        return Collections.singletonList("");
    }
    if (n == 1) {
        return Arrays.asList("0", "1", "8");
    }
    List<String> subResults = helper(n - 2, finalLength);
    List<String> results = new ArrayList<>();
    for (String sub : subResults) {
        if (n != finalLength) {
            results.add("0" + sub + "0");
        }
        results.add("1" + sub + "1");
        results.add("6" + sub + "9");
        results.add("8" + sub + "8");
        results.add("9" + sub + "6");
    }
    return results;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return Collections.emptyList();
    }
    if (n == 1) {
        return Arrays.asList("0", "1", "8");
    }
    if (n == 2) {
        return Arrays.asList("11", "69", "88", "96");
    }

    List<String> subResult = centerSymmetricNumbers(n - 2);
    List<String> result = new ArrayList<>();

    for (String s : subResult) {
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
        if (n != 2) { // Avoid adding unnecessary zeros at the start for the outermost layer
            result.add("0" + s + "0");
        }
    }

    return result;
}

