private static List<String> generateCenterSymmetricNumbers(int currentLength, int targetLength) {
    if (currentLength == 0) {
        return new ArrayList<>(List.of(""));
    }
    if (currentLength == 1) {
        return new ArrayList<>(List.of("0", "1", "8"));
    }

    List<String> centerSymmetricNumbers = generateCenterSymmetricNumbers(currentLength - 2, targetLength);
    List<String> result = new ArrayList<>();

    for (String num : centerSymmetricNumbers) {
        if (currentLength != targetLength) {
            result.add("0" + num + "0");
        }
        result.add("1" + num + "1");
        result.add("6" + num + "9");
        result.add("8" + num + "8");
        result.add("9" + num + "6");
    }

    return result;
