private static void generateCenterSymmetricNumbers(int originalLength, int currentLength, String current, List<String> result) {
    if (currentLength == 0) {
        if (originalLength != 1 || current.charAt(0) != '0') {
            result.add(current);
        }
        return;
    }

    if (currentLength == 1) {
        result.add(current + "0");
        result.add(current + "1");
        result.add(current + "8");
        return;
    }

    generateCenterSymmetricNumbers(originalLength, currentLength - 2, "1" + current + "1", result);
    generateCenterSymmetricNumbers(originalLength, currentLength - 2, "6" + current + "9", result);
    generateCenterSymmetricNumbers(originalLength, currentLength - 2, "8" + current + "8", result);
    generateCenterSymmetricNumbers(originalLength, currentLength - 2, "9" + current + "6", result);
    if (currentLength < originalLength) {
        generateCenterSymmetricNumbers(originalLength, currentLength - 2, "0" + current + "0", result);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3 || points[0].length != 2 || points[1].length != 2 || points[2].length != 2) {
        throw new IllegalArgumentException("Input must be an array of three points with two coordinates each.");
    }

    int[] p0 = points[0];
    int[] p1 = points[1];
    int[] p2 = points[2];

    // Calculate the area of the triangle formed by the points
    // Area = 0.5 * | x1(y2 - y3) + x2(y3 - y1) + x3(y1 - y2) |
    // If the area is 0, the points are collinear and do not form a boomerang
    int area = p0[0] * (p1[1] - p2[1]) + p1[0] * (p2[1] - p0[1]) + p2[0] * (p0[1] - p1[1]);

    return area != 0;
}

